    def to_min(text):
        # "HH:MM" (or an ISO stamp containing it) -> minutes after midnight
        if not isinstance(text, str):
            return None
        s = text.strip()
        if "T" in s:
            s = s.split("T")[1]
        parts = s.split(":")
        if len(parts) < 2:
            return None
        try:
            return int(parts[0]) * 60 + int(parts[1][:2])
        except ValueError:
            return None

    def offset_min(text):
        # "-07:00" -> -420
        if not isinstance(text, str):
            return 0
        s = text.strip().replace("UTC", "").replace("GMT", "")
        if s == "" or s == "Z":
            return 0
        sign = 1
        if s[0] == "-":
            sign = -1
            s = s[1:]
        elif s[0] == "+":
            s = s[1:]
        parts = s.split(":")
        try:
            h = int(parts[0])
            m = int(parts[1]) if len(parts) > 1 else 0
        except ValueError:
            return 0
        return sign * (h * 60 + m)

    def buffer_from_note(note):
        # e.g. "Please leave 15 minutes between any meeting with me and my other meetings."
        if not isinstance(note, str):
            return 0
        words = note.replace("-", " ").replace(",", " ").replace(".", " ").split()
        for i, w in enumerate(words):
            if i > 0 and w.lower().startswith("min") and words[i - 1].isdigit():
                return int(words[i - 1])
        return 0

    def pick_day(cal, day):
        entries = cal.get("days") if isinstance(cal, dict) else None
        if not isinstance(entries, list):
            return None
        want = str(day).strip().lower()[:3]
        for entry in entries:
            if isinstance(entry, dict) and str(entry.get("day", "")).strip().lower()[:3] == want:
                return entry
        if len(entries) == 1 and isinstance(entries[0], dict):
            return entries[0]
        return None

    def fmt(t):
        h, m = divmod(t, 60)
        return ("0" + str(h))[-2:] + ":" + ("0" + str(m))[-2:]

    people = [""]
    for name in attendees or []:
        if not isinstance(name, str):
            continue
        n = name.strip()
        if n == "" or n.lower() == "maya rivera":
            continue
        if n not in people:
            people.append(n)

    earliest_min = to_min(earliest) if earliest else None
    latest_min = to_min(latest_end) if latest_end else None

    starts = {}
    for day in days or []:
        lo = 0
        hi = 24 * 60
        if earliest_min is not None:
            lo = max(lo, earliest_min)
        if latest_min is not None:
            hi = min(hi, latest_min)
        blocks = []
        user_off = 0
        key = str(day).strip().lower()[:3]
        ok = True
        for person in people:
            cal = api.read_calendar(person, day)
            entry = pick_day(cal, day)
            if entry is None:
                ok = False
                break
            off = offset_min(cal.get("utc_offset", ""))
            if person == "":
                user_off = off
                if entry.get("day"):
                    key = entry.get("day")
            shift = user_off - off  # person's clock -> user's clock
            wh = cal.get("working_hours")
            if isinstance(wh, dict):
                wh = wh.get(entry.get("day"), wh.get(day))
            if isinstance(wh, str) and "-" in wh:
                parts = wh.split("-")
                ws = to_min(parts[0])
                we = to_min(parts[1])
                if ws is not None and we is not None:
                    lo = max(lo, ws + shift)
                    hi = min(hi, we + shift)
            buf = buffer_from_note(cal.get("note"))
            events = entry.get("events")
            if not isinstance(events, list):
                events = []
            for ev in events:
                if not isinstance(ev, dict):
                    continue
                show = str(ev.get("show_as", "busy")).strip().lower().replace("_", "").replace(" ", "")
                if show in ("free", "workingelsewhere"):
                    continue
                s = to_min(ev.get("start"))
                e = to_min(ev.get("end"))
                if s is None:
                    s = 0
                if e is None:
                    e = 24 * 60
                blocks.append((s + shift - buf, e + shift + buf))
        if not ok:
            continue
        found = []
        for t in range(0, 24 * 60, 15):
            end = t + minutes
            if t < lo or end > hi:
                continue
            if any(s < end and t < e for s, e in blocks):
                continue
            found.append(fmt(t))
        if found:
            starts[key] = found
    return {"starts": starts}
