    """Find every start time, by day, when the user and all the listed attendees are free for a meeting of the given length. days are mon to fri; earliest is the first allowed start and latest_end the time the meeting must end by, both HH:MM or empty. Returns the workable starts, earliest first."""
    week = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]

    def to_min(text):
        s = str(text).strip()
        if "T" in s:
            s = s.split("T")[-1]
        elif " " in s:
            s = s.split(" ")[-1]
        parts = s.split(":")
        return int(parts[0]) * 60 + (int(parts[1][:2]) if len(parts) > 1 else 0)

    def to_offset(text):
        s = str(text or "").strip()
        if s == "" or s in ("Z", "z"):
            return 0
        sign = 1
        if s[0] == "-":
            sign = -1
            s = s[1:]
        elif s[0] == "+":
            s = s[1:]
        try:
            if ":" in s:
                parts = s.split(":")
                return sign * (int(parts[0]) * 60 + int(parts[1]))
            if len(s) == 4:
                return sign * (int(s[:2]) * 60 + int(s[2:]))
            return sign * int(s) * 60
        except (ValueError, TypeError):
            return 0

    def day_index(name):
        key = str(name).strip().lower()[:3]
        return week.index(key) if key in week else -1

    def load(person):
        cal = None
        try:
            cal = api.read_calendar(person, "")
        except Exception:
            cal = None
        if isinstance(cal, dict) and isinstance(cal.get("days"), list):
            return cal
        merged = None
        for d in week[:5]:
            try:
                part = api.read_calendar(person, d)
            except Exception:
                part = None
            if isinstance(part, dict) and isinstance(part.get("days"), list):
                if merged is None:
                    merged = dict(part)
                    merged["days"] = []
                merged["days"] = merged["days"] + part["days"]
        return merged

    def digest(cal):
        off = to_offset(cal.get("utc_offset", ""))
        ws, we = 0, 1440
        wh = cal.get("working_hours", "")
        if isinstance(wh, str) and "-" in wh:
            try:
                a, b = wh.split("-")[:2]
                ws, we = to_min(a), to_min(b)
            except (ValueError, TypeError, IndexError):
                ws, we = 0, 1440
        busy = []
        for entry in cal.get("days", []):
