    people = [digest(user_cal)]
    seen = set()
    for name in attendees or []:
        n = str(name).strip()
        low = n.lower()
        if n == "" or low == user_name or low in seen:
            continue
        seen.add(low)
        cal = load(n)
        if cal is None:
            return {"starts": {}}
        people.append(digest(cal))

    user = people[0]
    lo = user["ws"]
    hi = user["we"]
    if earliest:
        lo = max(lo, to_min(earliest))
    if latest_end:
        hi = min(hi, to_min(latest_end))

    wanted = sorted(set([day_index(d) for d in (days or []) if day_index(d) >= 0]))
    starts = {}
    for di in wanted:
        found = []
        for t in range(0, 1440, 15):
            if t < lo or t + minutes > hi:
                continue
