def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    """Find every start time, by day, when the user and all the listed attendees are free for a meeting of the given length. days are mon to fri; earliest is the first allowed start and latest_end the time the meeting must end by, both HH:MM or empty. Returns the workable starts, earliest first."""
    order = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]

    def norm_day(d):
        return str(d).strip().lower()[:3]

    def to_min(s):
        parts = str(s).strip().split(":")
        hh = int(parts[0])
        mm = int(parts[1]) if len(parts) > 1 else 0
        return hh * 60 + mm

    def parse_offset(o):
        if isinstance(o, (int, float)) and not isinstance(o, bool):
            return int(round(o * 60))
        s = str(o or "").strip().upper().replace("UTC", "").replace("GMT", "").strip()
        if s == "" or s == "Z":
            return 0
        sign = 1
        if s[0] == "-":
            sign = -1
            s = s[1:]
        elif s[0] == "+":
            s = s[1:]
        if ":" in s:
            parts = s.split(":")
            hh = int(parts[0] or 0)
            mm = int(parts[1] or 0)
        elif len(s) >= 3:
            hh = int(s[:-2])
            mm = int(s[-2:])
        else:
            hh = int(s)
            mm = 0
        return sign * (hh * 60 + mm)

    def load(person):
        cal = api.read_calendar(person, "")
        if not isinstance(cal, dict) or not isinstance(cal.get("days"), list):
            raise ValueError("could not read calendar for " + (person or "user"))
        return cal

    user_cal = load("")
    user_name = str(user_cal.get("person", "") or "").strip().lower()
    user_off = parse_offset(user_cal.get("utc_offset", ""))

    cals = [user_cal]
    seen = set([user_name, ""])
    for a in attendees or []:
        key = str(a or "").strip().lower()
        if key in seen:
            continue
        seen.add(key)
        cals.append(load(a))

    # Build, per person, working windows and busy intervals in absolute
    # minutes of the week on the user's clock.
    people = []
    for cal in cals:
        shift = user_off - parse_offset(cal.get("utc_offset", ""))
        wh = str(cal.get("working_hours", "") or "").strip()
        windows = None
        if "-" in wh:
            try:
                bits = wh.split("-")
                ws = to_min(bits[0])
                we = to_min(bits[1])
                if we > ws:
                    windows = [(d * 1440 + ws + shift, d * 1440 + we + shift) for d in range(5)]
            except (ValueError, TypeError):
                windows = None
        busy = []
        for dayrec in cal.get("days", []):
            if not isinstance(dayrec, dict):
                continue
            dk = norm_day(dayrec.get("day", ""))
            if dk not in order:
                continue
            base = order.index(dk) * 1440 + shift
            for ev in dayrec.get("events", []) or []:
                if not isinstance(ev, dict):
                    continue
                if str(ev.get("show_as", "busy") or "busy").strip().lower() == "free":
                    continue
                try:
                    s = to_min(ev.get("start"))
                    e = to_min(ev.get("end"))
                except (ValueError, TypeError):
                    continue
                if e <= s:
                    continue
                busy.append((base + s, base + e))
        people.append((windows, busy))

    # how the user's calendar spells each day key
    day_keys = {}
    for dayrec in user_cal.get("days", []):
        if isinstance(dayrec, dict):
            dk = norm_day(dayrec.get("day", ""))
            if dk and dk not in day_keys:
                day_keys[dk] = dayrec.get("day")

    wanted = []
    for d in (days or ["mon", "tue", "wed", "thu", "fri"]):
        nd = norm_day(d)
        if nd in order and nd not in wanted:
            wanted.append(nd)

    lo = to_min(earliest) if str(earliest or "").strip() else 0
    hi = to_min(latest_end) if str(latest_end or "").strip() else 1440
    length = int(minutes)

    starts = {}
    for nd in wanted:
        base = order.index(nd) * 1440
        found = []
        for t in range(0, 1440, 15):
            if t < lo or t + length > hi or t + length > 1440:
                continue
            s = base + t
            e = s + length
            ok = True
            for windows, busy in people:
                if windows is not None and not any(w[0] <= s and e <= w[1] for w in windows):
                    ok = False
                    break
                if any(b[0] < e and s < b[1] for b in busy):
                    ok = False
                    break
            if ok:
                found.append(("0" + str(t // 60))[-2:] + ":" + ("0" + str(t % 60))[-2:])
        if found:
            starts[day_keys.get(nd, nd)] = found
    return {"starts": starts}
