                       earliest: str = "", latest_end: str = "") -> dict:
    """Find every start time, by day, when the user and all the listed attendees are free for a meeting of the given length. days are mon to fri; earliest is the first allowed start and latest_end the time the meeting must end by, both HH:MM or empty. Returns the workable starts, earliest first."""
    start_keys = ("start", "start_time", "starttime", "from", "begin", "starts", "starts_at", "start_at")
    end_keys = ("end", "end_time", "endtime", "to", "until", "ends", "ends_at", "end_at", "finish")
    dur_keys = ("duration", "duration_minutes", "minutes", "length", "duration_min", "mins")
    event_keys = ("events", "busy", "meetings", "appointments", "items", "entries",
                  "calendar", "schedule", "blocks", "bookings", "result", "data")
    work_keys = ("working_hours", "work_hours", "workhours", "workday", "work_day",
                 "hours", "office_hours", "business_hours", "working")
    fulls = {"mon": "monday", "tue": "tuesday", "wed": "wednesday", "thu": "thursday",
             "fri": "friday", "sat": "saturday", "sun": "sunday"}

    def find_times(s):
        out = []
        low = s.lower()
        n = len(low)
        last = -1
        for i in range(n):
            if low[i] != ":" or i == 0 or i == last:
                continue
            mm = low[i + 1:i + 3]
            if not (low[i - 1].isdigit() and len(mm) == 2 and mm.isdigit()):
                continue
            j = i - 1
            if j - 1 >= 0 and low[j - 1].isdigit():
                j -= 1
            h = int(low[j:i])
            m = int(mm)
            last = i + 3
            tail = low[i + 3:i + 8]
            if tail[:1] == ":":
                tail = low[i + 6:i + 11]
            tail = tail.replace(".", "").strip()
            if tail.startswith("pm") and h < 12:
                h += 12
            elif tail.startswith("am") and h == 12:
                h = 0
            if h <= 24 and m < 60:
                out.append(h * 60 + m)
        return out

    def parse_time(v):
        if isinstance(v, bool) or v is None:
            return None
        if isinstance(v, (int, float)):
            if 0 <= v <= 24:
                return int(round(v * 60))
            if v <= 1440:
                return int(v)
            return None
        if isinstance(v, dict):
            for k in ("dateTime", "date_time", "datetime", "time", "at", "value"):
                if k in v:
                    return parse_time(v[k])
            return None
        if not isinstance(v, str):
            return None
        s = v.strip().lower()
        if not s:
            return None
        ts = find_times(s)
        if ts:
            return ts[0]
        flat = s.replace(".", "").replace(" ", "")
        pm = flat.endswith("pm")
        am = flat.endswith("am")
        core = flat
        if pm or am:
            core = flat[:-2]
        if not core.isdigit():
            return None
        if len(core) <= 2:
            h = int(core)
            m = 0
        elif len(core) <= 4:
            h = int(core[:-2])
            m = int(core[-2:])
        else:
            return None
        if pm and h < 12:
            h += 12
        if am and h == 12:
            h = 0
        if h > 24 or m >= 60:
            return None
        return h * 60 + m

    def lead_alpha(s):
        out = ""
        for ch in s:
            if ch.isalpha():
                out += ch
            else:
                break
        return out

    def day_match(k, day):
        if not isinstance(k, str) or not isinstance(day, str):
            return False
        a = lead_alpha(k.strip().lower())
        d = day.strip().lower()[:3]
        if len(d) < 3:
            return False
        return a == d or a == fulls.get(d, d)

    def lower_map(d):
        m = {}
        for k in d:
            if isinstance(k, str):
                m[k.strip().lower()] = d[k]
        return m

    def get_events(obj, day, depth):
        if isinstance(obj, (list, tuple)):
            return list(obj)
        if isinstance(obj, str):
            return [ln for ln in obj.splitlines() if ln.strip()]
        if isinstance(obj, dict) and depth < 5:
            for k in obj:
                if day_match(k, day) and isinstance(obj[k], (list, tuple, dict, str)):
                    return get_events(obj[k], day, depth + 1)
            m = lower_map(obj)
            for name in event_keys:
                if name in m and isinstance(m[name], (list, tuple, dict, str)):
                    return get_events(m[name], day, depth + 1)
        return []

    def first_of(m, keys):
        for k in keys:
            if k in m and m[k] is not None and m[k] != "":
                return m[k]
        return None

    def interval(ev, day):
        if isinstance(ev, str):
            low = ev.lower()
            if "cancel" in low or "declin" in low:
                return None
            if "working hours" in low or "work hours" in low or "office hours" in low:
                return None
            ts = find_times(ev)
            if len(ts) >= 2:
                return (ts[0], ts[1])
            if "all day" in low or "all-day" in low:
                return (0, 1440)
            return None
        if isinstance(ev, (list, tuple)):
            if len(ev) >= 2:
                s = parse_time(ev[0])
                e = parse_time(ev[1])
                if s is not None and e is not None:
                    return (s, e)
            return None
        if not isinstance(ev, dict):
            return None
        m = lower_map(ev)
        for k in ("day", "weekday"):
            if k in m and isinstance(m[k], str) and m[k].strip() and not day_match(m[k], day):
                return None
        for k in ("status", "response", "rsvp", "show_as", "showas", "transparency",
                  "availability", "state"):
            val = m.get(k)
            if isinstance(val, str):
                val = val.strip().lower()
                if "cancel" in val or "declin" in val or val in ("free", "transparent", "available"):
                    return None
        for k in ("cancelled", "canceled", "declined", "free", "is_cancelled", "is_canceled", "is_free"):
            if m.get(k) is True:
                return None
        if "busy" in m and m["busy"] is False:
            return None
        for k in ("all_day", "allday", "all-day", "is_all_day"):
            if m.get(k) is True:
                return (0, 1440)
        s = parse_time(first_of(m, start_keys))
        e = parse_time(first_of(m, end_keys))
        if s is None:
            tv = m.get("time")
            if isinstance(tv, str):
                ts = find_times(tv)
                if len(ts) >= 2:
                    return (ts[0], ts[1])
                if len(ts) == 1:
                    s = ts[0]
        if s is None:
            return None
        if e is None:
            d = first_of(m, dur_keys)
            if isinstance(d, (int, float)) and not isinstance(d, bool):
                e = s + int(d)
            else:
                return None
        return (s, e)

    def parse_offset(v, kl):
        if isinstance(v, bool) or v is None:
            return None
        if isinstance(v, (int, float)):
            if "min" in kl:
                return int(v)
            if "hour" in kl or abs(v) <= 16:
                return int(round(v * 60))
            return int(v)
        if isinstance(v, dict):
            for k in v:
                if isinstance(k, str) and "offset" in k.lower():
                    r = parse_offset(v[k], k.lower())
                    if r is not None:
                        return r
            return None
        if not isinstance(v, str):
            return None
        s = v.strip().upper()
        prefixed = False
        for p in ("UTC", "GMT"):
            if s.startswith(p):
                s = s[len(p):].strip()
                prefixed = True
        if s in ("", "Z"):
            return 0 if (prefixed or s == "Z") else None
        sign = 1
        if s[0] in "+-":
            if s[0] == "-":
                sign = -1
            s = s[1:].strip()
        elif not (prefixed or "offset" in kl):
            return None
        if ":" in s:
            parts = s.split(":")
            if parts[0].isdigit() and parts[1][:2].isdigit():
                return sign * (int(parts[0]) * 60 + int(parts[1][:2]))
            return None
        if s.isdigit() and len(s) == 4:
            return sign * (int(s[:2]) * 60 + int(s[2:]))
        try:
            return sign * int(round(float(s) * 60))
        except ValueError:
            return None

    def cal_offset(cal):
        if not isinstance(cal, dict):
            return None
        for k in cal:
            if not isinstance(k, str):
                continue
            kl = k.strip().lower()
            if "offset" in kl or "ahead" in kl or "behind" in kl or "timezone" in kl or kl in ("tz", "time_zone", "utc", "zone"):
                val = parse_offset(cal[k], kl)
                if val is not None:
                    if "behind" in kl:
                        val = -val
                    rel = any(w in kl for w in ("user", "ahead", "behind", "relative", "maya"))
                    return (rel, val)
        return None

    def pair_from(v):
        if isinstance(v, dict):
            m = lower_map(v)
            s = parse_time(first_of(m, start_keys))
            e = parse_time(first_of(m, end_keys))
            if s is not None and e is not None:
                return (s, e)
            return None
        if isinstance(v, (list, tuple)) and len(v) == 2:
            s = parse_time(v[0])
            e = parse_time(v[1])
            if s is not None and e is not None:
                return (s, e)
            return None
        if isinstance(v, str):
            ts = find_times(v)
            if len(ts) >= 2:
                return (ts[0], ts[1])
        return None

    def work_window(cal, day):
        if isinstance(cal, str):
            for ln in cal.splitlines():
                low = ln.lower()
                if "working hours" in low or "work hours" in low or "office hours" in low:
                    r = pair_from(ln)
                    if r is not None and r[1] > r[0]:
                        return r
            return None
        if not isinstance(cal, dict):
            return None
        m = lower_map(cal)
        for k in work_keys:
            if k in m:
                v = m[k]
                if isinstance(v, dict):
                    for dk in v:
                        if day_match(dk, day):
                            v = v[dk]
                            break
                r = pair_from(v)
                if r is not None and r[1] > r[0]:
                    return r
        for a, b in (("work_start", "work_end"), ("day_start", "day_end"),
                     ("workday_start", "workday_end"), ("working_start", "working_end")):
            if a in m and b in m:
                s = parse_time(m[a])
                e = parse_time(m[b])
                if s is not None and e is not None and e > s:
                    return (s, e)
        return None

    def day_key(cal, day):
        if isinstance(cal, dict):
            m = lower_map(cal)
            v = m.get("day")
            if isinstance(v, str) and v.strip():
                return v
            for k in cal:
                if day_match(k, day):
                    return k
        return day

    def fmt(t):
        h, m = divmod(t, 60)
        return str(h).rjust(2, "0") + ":" + str(m).rjust(2, "0")

    try:
        need = int(minutes)
    except (TypeError, ValueError):
        need = 0
    result = {"starts": {}}
    if need <= 0:
        return result

    people = [""]
    seen = set()
    for a in attendees or []:
        if not isinstance(a, str):
            continue
        nm = a.strip()
        if not nm or nm.lower() in ("maya rivera", "me", "user") or nm.lower() in seen:
            continue
        seen.add(nm.lower())
        people.append(nm)

    want_lo = parse_time(earliest) if earliest else None
    want_hi = parse_time(latest_end) if latest_end else None

    done_days = set()
    for day in days or []:
        if day in done_days:
            continue
        done_days.add(day)
        cals = []
        ok = True
        for p in people:
            try:
                cal = api.read_calendar(p, day)
            except Exception:
                ok = False
                break
            if isinstance(cal, dict) and cal.get("error"):
                ok = False
                break
            cals.append(cal)
        if not ok:
            continue

        user_off = cal_offset(cals[0])
        user_abs = 0
        if user_off is not None and not user_off[0]:
            user_abs = user_off[1]

        lo = 0
        hi = 1440
        found_work = False
        busy = []
        for idx, cal in enumerate(cals):
            shift = 0
            if idx > 0:
                off = cal_offset(cal)
                if off is not None:
                    if off[0]:
                        shift = -off[1]
                    else:
                        shift = user_abs - off[1]
            ww = work_window(cal, day)
            if ww is not None:
                found_work = True
                lo = max(lo, ww[0] + shift)
                hi = min(hi, ww[1] + shift)
            for ev in get_events(cal, day, 0):
                iv = interval(ev, day)
                if iv is None:
                    continue
                s, e = iv
                if e <= s:
                    e = 1440
                busy.append((s + shift, e + shift))

        if not found_work:
            lo = 540
            hi = 1020
            if want_lo is not None and want_lo < lo:
                lo = want_lo
            if want_hi is not None and want_hi > hi:
                hi = want_hi
        if want_lo is not None:
            lo = max(lo, want_lo)
        if want_hi is not None:
            hi = min(hi, want_hi)
        lo = max(lo, 0)
        hi = min(hi, 1440)

        starts = []
        t = ((lo + 14) // 15) * 15
        while t + need <= hi:
            if all(not (s < t + need and e > t) for s, e in busy):
                starts.append(fmt(t))
            t += 15
        if starts:
            result["starts"][day_key(cals[0], day)] = starts
    return result
```

The guesses that most affect the answer:

- **Calendar shape:** it accepts a list of events, a dict holding a list under a key such as `events` or `busy` or under the day name, or plain text lines containing two times.
- **Events that don't block:** cancelled, declined or marked-free events are ignored; tentative ones count as busy.
- **Working hours:** if a calendar states working hours, starts stay inside everyone's. If none do, the window is 09:00–17:00, widened only when `earliest` or `latest_end` reaches outside it.
- **Time zones:** if a calendar carries a UTC offset or an offset relative to the user, that person's times are shifted onto the user's clock. Named zones such as "Europe/Paris" cannot be converted without imports and are treated as the user's own zone.
- **Unreadable calendars:** if any person's calendar raises or returns an error, that day is left out instead of assuming they are free.
- **Day keys:** each day is keyed by the user's calendar's own `day` value or matching key, falling back to the day as passed in.

