        "extra": {
            "type": "noul",
            "instructions": "Does `request` put any condition on the meeting other than who attends, how long it lasts, which weekdays of this week are allowed, an earliest start time and a latest end time? Examples: a room, an exact fixed start time, a recurring series, another week, a vague part of day.",
        },
        "length": {
            "type": "choice",
            "instructions": "How long, in minutes, should the meeting requested in `request` last?",
            "criteria": length_options,
        },
        "bound": {
            "type": "choice",
            "instructions": "Which time-of-day limit does `request` put on the meeting it asks for?",
            "criteria": {
                "end_by": "only a latest time by which the meeting must be finished",
                "start_from": "only an earliest time at or after which the meeting must start",
                "both": "both an earliest start time and a latest end time",
                "none": "no time-of-day limit at all",
                "other": "some other kind of time limit, such as an exact start time or a vague part of the day",
            },
        },
        "title_first": {
            "type": "choice",
            "instructions": "Which word of `request` is the first word of the name of the meeting to book (for example the 'hiring' of 'hiring debrief')? Do not count articles, lengths or people.",
            "criteria": word_options,
        },
        "title_last": {
            "type": "choice",
            "instructions": "Which word of `request` is the last word of the name of the meeting to book (for example the 'debrief' of 'hiring debrief')?",
            "criteria": word_options,
        },
    }
    for i in range(len(KNOWN_PEOPLE)):
        questions["person" + str(i)] = {
            "type": "noul",
            "instructions": "Does `request` name " + KNOWN_PEOPLE[i] + " (by full or first name) as someone who should attend the meeting it asks to book?",
        }
    for d in DAYS:
        questions["day_" + d[0]] = {
            "type": "noul",
            "instructions": "Is " + d[1] + " one of the days on which `request` allows the meeting to take place?",
        }
    if len(time_map) > 0:
        questions["end_time"] = {
            "type": "choice",
            "instructions": "Which clock time in `request` is the time by which the meeting must be finished?",
            "criteria": time_options,
        }
        questions["start_time"] = {
            "type": "choice",
            "instructions": "Which clock time in `request` is the earliest time at which the meeting may start?",
            "criteria": time_options,
        }

    state = {"request": request, "known_people": KNOWN_PEOPLE, "user": USER_NAME}
    try:
        ans = await kit.ask(state, questions)
    except Exception:
        return hand("could not get judgments on the request", "low", False)
    if not isinstance(ans, dict):
        return hand("unusable judgments on the request", "low", False)

    intent = picked(ans.get("intent"), questions["intent"]["criteria"])
    if intent is None:
        return hand("unclear whether this asks to book one meeting now", "medium", False)
    if intent == "not_booking":
        return hand("the request does not ask to book a meeting now", "low", True)
    if intent == "book_several":
        return hand("the request asks for more than one meeting", "medium", False)

    if yes_no(ans.get("outsider")) is not False:
        return hand("an attendee may not be one of the known people", "low", False)
    extra = ans.get("extra")
    extra_p = extra.get("noul") if isinstance(extra, dict) else None
    if not isinstance(extra_p, (int, float)) or extra_p >= 0.5:
        return hand("the request may carry a condition this program cannot check", "low", False)

    attendees = []
    for i in range(len(KNOWN_PEOPLE)):
        v = yes_no(ans.get("person" + str(i)))
        if v is None:
            return hand("unclear whether " + KNOWN_PEOPLE[i] + " should attend", "low", False)
        if v:
            attendees.append(KNOWN_PEOPLE[i])
    if len(attendees) == 0:
        return hand("no attendee identified", "low", False)
    low = request.lower()
    keyed = []
    for i in range(len(attendees)):
        pos = low.find(attendees[i].split()[0].lower())
        if pos < 0:
            pos = len(low) + i
        keyed.append([pos, i, attendees[i]])
    attendees = [k[2] for k in sorted(keyed)]

    days = []
    for d in DAYS:
        v = yes_no(ans.get("day_" + d[0]))
        if v is None:
            return hand("unclear whether " + d[1] + " is allowed", "low", False)
        if v:
            days.append(d[0])
    if len(days) == 0:
        return hand("no allowed day identified", "low", False)

    length = picked(ans.get("length"), length_options)
    if length is None or length not in LENGTHS:
        return hand("meeting length not identified", "low", False)
    minutes = int(length)

    bound = picked(ans.get("bound"), questions["bound"]["criteria"])
    if bound is None or bound == "other":
        return hand("time limit not understood", "low", False)
    earliest = ""
    latest_end = ""
    if bound in ["end_by", "both"]:
        c = picked(ans.get("end_time"), time_options) if len(time_map) > 0 else None
        if c is None or c == NONE or time_map.get(c) is None:
            return hand("latest end time not identified", "low", False)
        latest_end = time_map[c]
    if bound in ["start_from", "both"]:
        c = picked(ans.get("start_time"), time_options) if len(time_map) > 0 else None
        if c is None or c == NONE or time_map.get(c) is None:
            return hand("earliest start time not identified", "low", False)
        earliest = time_map[c]

    first = picked(ans.get("title_first"), word_options)
    last = picked(ans.get("title_last"), word_options)
    if first is None or last is None or first == NONE or last == NONE:
        return hand("meeting name not identified", "low", False)
    title = find_title(raw, clean, first, last)
    if title is None:
        return hand("meeting name not identified", "low", False)

    try:
        res = await kit.procedure("find_shared_starts", attendees=attendees, days=days, minutes=minutes, earliest=earliest, latest_end=latest_end)
    except Exception:
        return hand("find_shared_starts failed", "low", False)
    if not isinstance(res, dict) or not isinstance(res.get("starts"), dict):
        return hand("find_shared_starts gave no usable answer", "low", False)
    starts = {}
    for k in res["starts"]:
        starts[str(k).lower()] = res["starts"][k]

    day = None
    start = None
    for d in DAYS:
        if d[0] in days and isinstance(starts.get(d[0]), list) and len(starts[d[0]]) > 0:
            day = d
            start = starts[d[0]][0]
            break
    if day is None:
        return hand("no shared start fits the request; nothing was booked, tell the user", "low", False)
    if not valid_clock(start):
        return hand("unexpected start format from find_shared_starts", "low", False)
    begin = to_minutes(start)
    finish = begin + minutes
    if earliest != "" and begin < to_minutes(earliest):
        return hand("offered start is before the earliest allowed", "low", False)
    if latest_end != "" and finish > to_minutes(latest_end):
        return hand("offered start ends after the latest allowed end", "low", False)
    hm = divmod(finish, 60)
    end = pad(hm[0]) + ":" + pad(hm[1])

    if len(attendees) > 1:
        who = ", ".join(attendees[:-1]) + " and " + attendees[-1]
    else:
        who = attendees[0]
    reply = "Booked " + title + " on " + day[1] + " from " + start + " to " + end + " with " + who + "."
    return {
        "action": "book_time",
        "arguments": {"title": title, "day": day[0], "start": start, "minutes": minutes, "attendees": attendees},
        "reply": reply,
    }
