```python
def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    order = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]

    def key3(d):
        return str(d).strip().lower()[:3]

    def to_min(s):
        parts = str(s).strip().split(":")
        return int(parts[0]) * 60 + (int(parts[1]) if len(parts) > 1 else 0)

    def offset(s):
        s = str(s or "").strip().upper().replace("UTC", "").replace("GMT", "").strip()
        if not s or s == "Z":
            return 0
        sign = 1
        if s[0] == "-":
            sign = -1
            s = s[1:]
        elif s[0] == "+":
            s = s[1:]
        try:
            if ":" in s:
                return sign * to_min(s)
            if len(s) == 4:
                return sign * (int(s[:2]) * 60 + int(s[2:]))
            return sign * int(float(s) * 60)
        except Exception:
            return 0

    def hours(s):
        try:
            s = str(s).replace("–", "-").replace(" to ", "-")
            a, b = s.split("-")[:2]
            a = to_min(a)
            b = to_min(b)
            if b <= a:
                b += 1440
            return (a, b)
        except Exception:
            return (0, 1440)

    def buffer_of(note):
        n = str(note or "").lower()
        if not n:
            return 0
        if not any(k in n for k in ["between", "buffer", "gap", "leave", "before and after",
                                    "either side", "back-to-back", "back to back", "breathing"]):
            return 0
        if "half an hour" in n or "half-hour" in n or "half hour" in n:
            return 30
        if "quarter of an hour" in n or "quarter-hour" in n or "quarter hour" in n:
            return 15
        names = {"five": 5, "ten": 10, "fifteen": 15, "twenty": 20, "thirty": 30,
                 "forty-five": 45, "forty five": 45, "sixty": 60, "one": 1, "two": 2, "an": 1, "a": 1}
        words = n.replace(",", " ").replace(".", " ").replace("-minute", " minute").replace("-hour", " hour").split()
        for i, w in enumerate(words):
            if i == 0:
                continue
            prev = words[i - 1]
            val = None
            if prev.isdigit():
                val = int(prev)
            elif prev in names:
                val = names[prev]
            if val is None:
                continue
            if w.startswith("min"):
                return val
            if w.startswith("hour") or w.startswith("hr"):
                return val * 60
        return 0

    people = [""] + [a for a in attendees if a]
    cals = []
    for p in people:
        cal = api.read_calendar(p, "")
        if not isinstance(cal, dict):
            cal = {}
        cals.append(cal)

    user_off = offset(cals[0].get("utc_offset", ""))

    infos = []
    for cal in cals:
        delta = user_off - offset(cal.get("utc_offset", ""))
        buf = buffer_of(cal.get("note", ""))
        default_wh = cal.get("working_hours", "")
        windows = []
        busy = []
        for i, d in enumerate(cal.get("days", []) or []):
            k = key3(d.get("day", ""))
            idx = order.index(k) if k in order else i
            base = idx * 1440 + delta
            wh = d.get("working_hours", default_wh)
            if wh:
                w = hours(wh)
            else:
                w = (0, 1440)
            windows.append((base + w[0], base + w[1]))
            for ev in d.get("events", []) or []:
                show = str(ev.get("show_as", "busy")).strip().lower()
                status = str(ev.get("status", "")).strip().lower()
                if show == "free" or status.startswith("cancel") or status == "declined":
                    continue
                try:
                    s = to_min(ev.get("start"))
                    e = to_min(ev.get("end"))
                except Exception:
                    continue
                if e < s:
                    e += 1440
                busy.append((base + s - buf, base + e + buf))
        infos.append((windows, busy))

    wanted = [key3(d) for d in (days or [])]
    lo = to_min(earliest) if earliest else 0
    hi = to_min(latest_end) if latest_end else 1440

    result = {}
    for i, d in enumerate(cals[0].get("days", []) or []):
        name = d.get("day", "")
        k = key3(name)
        if wanted and k not in wanted:
            continue
        idx = order.index(k) if k in order else i
        found = []
        s = 0
        while s + minutes <= 1440:
            if s >= lo and s + minutes <= hi:
                a = idx * 1440 + s
                b = a + minutes
                ok = True
                for windows, busy in infos:
                    if not any(ws <= a and b <= we for ws, we in windows):
                        ok = False
                        break
                    if any(bs < b and a < be for bs, be in busy):
                        ok = False
                        break
                if ok:
                    h, m = divmod(s, 60)
                    found.append(("0" + str(h))[-2:] + ":" + ("0" + str(m))[-2:])
            s += 15
        if found:
            result[name] = found
    return {"starts": result}
```

The function reads each person's whole week once and returns the quarter-hour starts that fit everyone. Only one truncated run was available and it shows no chosen slots, so the rules below are my reading of the calendar data rather than something I could check against an accepted answer:

- **Time zones:** each person's events and working hours are taken as being on their own clock and shifted to Maya's using `utc_offset`.
- **Working hours:** a meeting must sit entirely inside every person's working hours, Maya's included.
- **Free events:** anything with `show_as` of "free" (Gym, Reading time, the optional lunch) does not block. Every other value, including something like "tentative", blocks.
- **Buffer notes:** a note like Dana's "leave half an hour between..." widens that person's busy events by that amount on both sides. Other kinds of note (for example "no meetings on Fridays") are not understood and are ignored.
- **Day names:** days are matched on their first three letters, and the result uses the day keys from Maya's calendar. An empty `days` list means every day on her calendar.

