def clean(memories):
    out = []
    seen = []
    if not isinstance(memories, list):
        return out
    for m in memories:
        if isinstance(m, dict) and isinstance(m.get("name"), str) and m.get("name"):
            if m["name"] not in seen:
                seen.append(m["name"])
                out.append(m)
    return out


async def decide(request, kit):
    text = request if isinstance(request, str) else str(request)

    recalled = []
    try:
        recalled = clean(await kit.recall(text, 4))
    except Exception:
        recalled = []

    recalled_acting = [m for m in recalled if not bool(m.get("read_only"))]
    recalled_readonly = [m for m in recalled if bool(m.get("read_only"))]
    listed_acting = [m for m in MEMORIES if not m["read_only"]]
    listed_readonly = [m for m in MEMORIES if m["read_only"]]

    # Step 1: does the request ask for the job's action now?
    p = None
    try:
        answer = await kit.ask(
            {"request": text},
            {"acts_now": {"type": "noul", "instructions": ACT_QUESTION}},
        )
        p = float(answer["acts_now"]["noul"])
    except Exception:
        p = None

    if p is None:
        # Step 4: Jev failed, fall back to the closest recalled memory.
        if recalled:
            return {"serve": recalled[0]["name"]}
        return {"handoff": "could not judge the request and no memory was recalled", "route": "medium"}

    # Step 2: not asking for the action now.
    if p < 0.5:
        if recalled_readonly:
            return {"serve": recalled_readonly[0]["name"]}
        if listed_readonly:
            return {"serve": listed_readonly[0]["name"]}
        return {
            "handoff": "the request does not ask for a meeting to be booked now",
            "read_only": True,
        }

    # Step 3: asks for the action now, pick an acting memory.
    candidates = recalled_acting if recalled_acting else listed_acting
    if not candidates:
        return {"handoff": "booking request with no acting memory available", "route": "medium"}
    if len(candidates) == 1:
        return {"serve": candidates[0]["name"]}

    criteria = {}
    for m in candidates:
        desc = m.get("description")
        criteria[m["name"]] = desc if isinstance(desc, str) and desc else m["name"]

    try:
        answer = await kit.ask(
            {"request": text, "kinds": criteria},
            {"kind": {"type": "choice", "instructions": KIND_QUESTION, "criteria": criteria}},
        )
        choice = answer["kind"]["choice"]
        if choice in criteria:
            return {"serve": choice}
    except Exception:
        pass

    # Jev failed here: closest acting memory (never a read-only one for an act-now request).
    return {"serve": candidates[0]["name"]}
