def handoff(why, route, memory, read_only):
    out = {"handoff": why}
    if route:
        out["route"] = route
    if memory:
        out["memory"] = memory
    if read_only:
        out["read_only"] = True
    return out


def give_up(why, extra):
    mem = MEMORY_SINGLE
    if extra:
        mem = mem + " Learned on this request: " + extra
    return handoff(why, "low", mem, False)


def parse_time(text):
    s = str(text).lower().replace(".", "").replace(" ", "")
    suffix = ""
    if s.endswith("am") or s.endswith("pm"):
        suffix = s[len(s) - 2:]
        s = s[:len(s) - 2]
    if ":" in s:
        parts = s.split(":")
        if len(parts) != 2:
            return None
        hs = parts[0]
        ms = parts[1]
    else:
        if not suffix:
            return None
        hs = s
        ms = "0"
    if not hs.isdigit() or not ms.isdigit():
        return None
    h = int(hs)
    m = int(ms)
    if suffix == "pm" and h < 12:
        h = h + 12
    if suffix == "am" and h == 12:
        h = 0
    if h > 23 or m > 59:
        return None
    return h * 60 + m


def fmt_time(total):
    h, m = divmod(total, 60)
    return ("0" if h < 10 else "") + str(h) + ":" + ("0" if m < 10 else "") + str(m)


def clean_word(w):
    return w.strip(".,;:!?()[]\"'-+/")


