async def decide(request, kit):
    text = request if isinstance(request, str) else str(request)

    question = {
        "type": "noul",
        "instructions": (
            "Read the user's message in `request`. The assistant's job exists to perform one action: "
            "actually putting new meeting time on the calendar this week for the user and the people named. "
            "Is the user asking for that action to be carried out now? "
            "Answer yes when the message, taken as a whole, wants a new meeting (or several) actually scheduled now, "
            "even if it is terse or written as shorthand notes, even if the ask sits between unrelated remarks, "
            "and even if it mentions days or times to avoid or other constraints. "
            "Answer no when the message is only a question about meetings or availability, only wants options looked up "
            "or listed, asks to change, move, cancel, hold or draft something, says to wait or not to do it yet, "
            "withdraws an earlier ask, reports that it is already done, is vague about doing it at some later unspecified time, "
            "or concerns something other than scheduling a meeting."
        ),
    }

    asks_now = None
    try:
        answer = await kit.ask({"request": text}, {"asks_now": question})
        p = answer["asks_now"]["noul"]
        if p > 0.7:
            asks_now = True
        elif p < 0.3:
            asks_now = False
        else:
            asks_now = p >= 0.5
    except Exception:
        asks_now = None

    memories = []
    try:
        got = await kit.recall(text, 4)
        if got:
            memories = [m for m in got if isinstance(m, dict) and m.get("name")]
    except Exception:
        memories = []

    if not memories:
        return {"handoff": "no stored memory was recalled for this request", "route": "medium"}

    if asks_now is None:
        return {"serve": memories[0]["name"]}

    if asks_now:
        acting = [m for m in memories if not m.get("read_only")]
        if not acting:
            return {"serve": memories[0]["name"]}
        if len(acting) == 1:
            return {"serve": acting[0]["name"]}
        criteria = {}
        for m in acting:
            criteria[m["name"]] = str(m.get("description", ""))
        try:
            pick = await kit.ask(
                {"request": text, "kinds": criteria},
                {"kind": {
                    "type": "choice",
                    "instructions": (
                        "Each option is a kind of request, described in `kinds` and in the criteria. "
                        "Choose the kind whose description best fits the message in `request`. "
                        "Pay attention to how many separate meetings the message wants: one meeting with several "
                        "candidate days is still one meeting."
                    ),
                    "criteria": criteria,
                }},
            )
            choice = pick["kind"]["choice"]
            if choice in criteria:
                return {"serve": choice}
        except Exception:
            pass
        return {"serve": acting[0]["name"]}

    passive = [m for m in memories if m.get("read_only")]
    if passive:
        return {"serve": passive[0]["name"]}
    return {"serve": memories[0]["name"]}

