    def to_min(t):
        if not isinstance(t, str):
            return None
        parts = t.strip().split(":")
        if len(parts) != 2:
            return None
        if not (parts[0].isdigit() and parts[1].isdigit()):
            return None
        h = int(parts[0])
        m = int(parts[1])
        if h > 23 or m > 59:
            return None
        return h * 60 + m

    def fmt(total):
        h, m = divmod(total, 60)
        hs = str(h)
        ms = str(m)
        if len(hs) < 2:
