    for i, name in enumerate(PEOPLE):
        questions["person" + str(i)] = {
            "type": "noul",
            "instructions": "Is " + name + " (possibly referred to by first name only) one of the people the meeting that `request` asks to book should include as an attendee?",
        }
    for d in DAYS:
        questions["day_" + d] = {
            "type": "noul",
            "instructions": "Is " + DAY_NAMES[d] + " one of the days on which the meeting in `request` may be scheduled, that is, inside the day window the user asks for? A range such as Tuesday to Thursday includes every day in between. Days the user rules out, or does not mention as possible, are not.",
        }
    len_criteria = {}
    for n in LENGTHS:
        len_criteria[n] = "the meeting should last " + n + " minutes"
    len_criteria["other"] = "another length, or no length is stated"
    questions["minutes"] = {
        "type": "choice",
        "instructions": "How long should the meeting that `request` asks to book last, in minutes?",
        "criteria": len_criteria,
    }
    title_criteria = {}
    for t in TITLES:
        title_criteria[t] = "the meeting is called or is about a " + t.lower()
    title_criteria["other"] = "the meeting has some other name or purpose, or none is given"
    questions["title"] = {
        "type": "choice",
        "instructions": "What is the name of the meeting that `request` asks to book? Ignore unrelated chatter around the booking request.",
        "criteria": title_criteria,
    }
    early_criteria = {}
    late_criteria = {}
    for c in time_opts:
        early_criteria[c] = "the meeting must not start before " + c
        late_criteria[c] = "the meeting must be over by " + c
    early_criteria["none"] = "no earliest start time is given"
    late_criteria["none"] = "no latest end time is given"
    questions["earliest"] = {
        "type": "choice",
        "instructions": "Which clock time, if any, does `request` give as the earliest the meeting may start (for example 'starting no earlier than', 'at or after', 'earliest possible start at')? A time by which the meeting must be finished is not an earliest start.",
        "criteria": early_criteria,
    }
    questions["latest_end"] = {
        "type": "choice",
        "instructions": "Which clock time, if any, does `request` give as the time the meeting must be finished by (for example 'done by', 'ending no later than')? A time the meeting may start from is not a latest end.",
        "criteria": late_criteria,
    }
    questions["has_time_bound"] = {
        "type": "noul",
        "instructions": "Does `request` put any time-of-day limit on the meeting, such as an earliest start time or a time it must be finished by?",
    }
    questions["other_people"] = {
        "type": "noul",
        "instructions": "Does `request` ask for the meeting to include any attendee who is neither the user (`user`, 'me') nor one of `known_people`?",
    }
    questions["other_constraint"] = {
        "type": "noul",
        "instructions": "Apart from the attendees, the length, the allowed days, an earliest start time and a latest end time, does `request` place another requirement on when the meeting happens, such as an exact start time, a week other than this week, or being before or after some other event? Remarks that rule days out count as allowed days, not as another requirement.",
    }
    questions["one_meeting_now"] = {
        "type": "noul",
        "instructions": "Does `request` ask to actually book exactly one meeting now (not several meetings, and not merely to hold, draft, move, cancel or ask about one)?",
    }

    try:
