    if l_choice != "none":
        l_min = to_min(l_choice)
        if l_min is None:
            return hand("latest end malformed")
        latest_end = fmt(l_min)
    if e_min is not None and l_min is not None and e_min + minutes > l_min:
        return hand("time bounds leave no room for the meeting")

    try:
        res = await kit.procedure("find_shared_starts", attendees=attendees, days=days, minutes=minutes, earliest=earliest, latest_end=latest_end)
    except Exception:
        return hand("find_shared_starts failed")
    if not isinstance(res, dict) or not isinstance(res.get("starts"), dict):
        return hand("find_shared_starts gave no usable answer")
    by_day = {}
    for k in res["starts"]:
        v = res["starts"][k]
        if isinstance(k, str) and isinstance(v, list):
            by_day[k.strip().lower()[:3]] = v

    picked_day = None
    picked = None
    for d in days:
        good = []
        for s in by_day.get(d, []):
            sm = to_min(s)
            if sm is None:
                return hand("find_shared_starts returned a malformed start")
            if e_min is not None and sm < e_min:
                continue
            if l_min is not None and sm + minutes > l_min:
                continue
            if sm + minutes > 24 * 60:
                continue
            good.append(sm)
        if good:
            picked_day = d
            picked = min(good)
            break
    if picked_day is None:
        return hand("no shared start satisfies the request; nothing was booked, the user needs to be told (days " + ", ".join(days) + ", " + str(minutes) + " min, attendees " + ", ".join(attendees) + ")")

    start = fmt(picked)
    end = fmt(picked + minutes)
    return {
        "action": "book_time",
        "arguments": {"title": title, "day": picked_day, "start": start, "minutes": minutes, "attendees": attendees},
        "reply": "Booked " + title + " on " + DAY_NAMES[picked_day] + " from " + start + " to " + end + " with " + ", ".join(attendees) + ".",
    }

