DEFAULT_BOOKING = "book_single_meeting"

ACT_INSTRUCTIONS = (
    "This job is a personal calendar assistant whose one action is booking meetings "
    "on the calendar this week for the user and the people named. Read `request` and "
    "decide whether the user is asking to have a meeting (one or several) actually "
    "booked right now. The request may be terse, informal, or buried among unrelated "
    "chatter about other topics; if somewhere in it the user asks for a meeting to be "
    "booked, scheduled, set up, arranged or locked in now, it still counts as asking "
    "for the booking. It does NOT count if the request only asks a question (about "
    "availability, about whether something is on the calendar, about possible slots), "
    "asks to only list or suggest options without booking, asks to wait or hold off, "
    "says the meeting is already booked or is no longer needed, talks about doing it "
    "at some later time with no urgency, asks to change, cancel, move, reschedule or "
    "merely draft something, or is about something other than booking a meeting."
)

ACT_CRITERIA = {
    "book_now": "The request asks to actually book one or more meetings now, even if "
                "surrounded by unrelated chatter.",
    "not_now": "The request only asks a question, asks to wait or hold off, says it is "
               "already done or no longer needed, defers to a later time without urgency, "
               "asks to change, cancel, move or draft something, lists options without "
               "booking, or is about something other than booking a meeting.",
}

PICK_INSTRUCTIONS = (
    "The user's `request` asks to book meetings on the calendar now. The options are "
    "kinds of request, each described in `memories` and in the option text. Choose the "
    "kind that best fits `request`. Pay attention to how many separate meetings the "
    "request asks for: one meeting offered several candidate days is still a single "
    "meeting."
)


async def decide(request, kit):
    recalled = None

    async def get_recalled():
        try:
            found = await kit.recall(request, k=4)
        except Exception:
            found = []
        out = []
        for m in found or []:
            if isinstance(m, dict) and isinstance(m.get("name"), str):
                out.append(m)
        return out

    def closest(mems):
        if mems:
            return {"serve": mems[0]["name"]}
        return {"serve": DEFAULT_BOOKING}

    # Step 1: one judgment on whether the request asks for the booking now.
    try:
        reply = await kit.ask(
            {"request": request},
            {"act": {"type": "choice", "instructions": ACT_INSTRUCTIONS, "criteria": ACT_CRITERIA}},
        )
        verdict = reply["act"]["choice"]
        if verdict not in ACT_CRITERIA:
            raise ValueError("unexpected answer")
    except Exception:
        recalled = await get_recalled()
        return closest(recalled)

    # Step 2: not a booking request.
    if verdict != "book_now":
        return {"serve": NON_BOOKING}

    # Step 3: recall and keep the memories that are not read-only.
    recalled = await get_recalled()
    writable = []
    seen = []
    for m in recalled:
        if not m.get("read_only") and m["name"] not in seen:
            seen.append(m["name"])
            writable.append(m)

    if len(writable) == 0:
        return {"serve": DEFAULT_BOOKING}
    if len(writable) == 1:
        return {"serve": writable[0]["name"]}

    criteria = {}
    listing = []
    for m in writable:
        desc = str(m.get("description", ""))
        criteria[m["name"]] = desc
        listing.append({"name": m["name"], "description": desc})

    try:
        reply = await kit.ask(
            {"request": request, "memories": listing},
            {"pick": {"type": "choice", "instructions": PICK_INSTRUCTIONS, "criteria": criteria}},
        )
        picked = reply["pick"]["choice"]
    except Exception:
        return {"serve": writable[0]["name"]}

    if picked in criteria:
        return {"serve": picked}
    return {"serve": writable[0]["name"]}
