```python
def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    """Find every start time, by day, when the user and all the listed attendees are free for a meeting of the given length. days are mon to fri; earliest is the first allowed start and latest_end the time the meeting must end by, both HH:MM or empty. Returns the workable starts, earliest first."""

    def to_min(s):
        parts = str(s).strip().split(":")
        return int(parts[0]) * 60 + (int(parts[1]) if len(parts) > 1 else 0)

    def fmt(t):
        return str(t // 60).zfill(2) + ":" + str(t % 60).zfill(2)

    def offset(s):
        try:
            s = str(s or "").strip().upper().replace("UTC", "").replace("GMT", "").strip()
            if not s or s == "Z":
                return 0
            sign = 1
            if s[0] in "+-":
                if s[0] == "-":
                    sign = -1
                s = s[1:]
            if ":" in s:
                h, m = s.split(":")[0], s.split(":")[1]
            elif len(s) == 4:
                h, m = s[:2], s[2:]
            else:
                h, m = s, "0"
            return sign * (int(h) * 60 + int(m))
        except Exception:
            return 0

    def work_hours(wh, key):
        try:
            if isinstance(wh, dict):
                if key in wh:
                    wh = wh[key]
                elif "start" in wh and "end" in wh:
                    return to_min(wh["start"]), to_min(wh["end"])
            if isinstance(wh, dict):
                return to_min(wh["start"]), to_min(wh["end"])
            if isinstance(wh, (list, tuple)):
                return to_min(wh[0]), to_min(wh[1])
            parts = str(wh).replace("–", "-").replace(" to ", "-").split("-")
            return to_min(parts[0]), to_min(parts[1])
        except Exception:
            return 9 * 60, 17 * 60

    def note_buffer(note):
        if not note:
            return 0
        text = str(note).lower()
        if not any(k in text for k in ["between", "buffer", "gap", "leave", "break", "apart"]):
            return 0
        if "half an hour" in text or "half hour" in text or "half-hour" in text:
            return 30
        if "quarter of an hour" in text or "quarter hour" in text or "quarter-hour" in text:
            return 15
        if "forty-five" in text or "forty five" in text:
            return 45
        for ch in ".,;:!?()-":
            text = text.replace(ch, " ")
        words = {"five": 5, "ten": 10, "fifteen": 15, "twenty": 20, "thirty": 30,
                 "forty": 40, "sixty": 60, "ninety": 90, "one": 1, "two": 2,
                 "an": 1, "a": 1}
        toks = text.split()
        for i, tok in enumerate(toks):
            digits = ""
            for ch in tok:
                if ch.isdigit():
                    digits += ch
                else:
                    break
            rest = tok[len(digits):]
            n = None
            unit = ""
            if digits:
                n = int(digits)
                unit = rest if rest else (toks[i + 1] if i + 1 < len(toks) else "")
            elif tok in words:
                n = words[tok]
                unit = toks[i + 1] if i + 1 < len(toks) else ""
            if n is None:
                continue
            if unit.startswith("min"):
                return n
            if unit.startswith("hour") or unit.startswith("hr"):
                return n * 60
        return 0

    def day_entry(cal, key):
